    "debug": False,
    "page_size": 25,
    "features": [],
}


def _parse_debug(value) -> bool:
    return bool(value)


def _parse_page_size(value) -> int:
    page_size = int(value)
    if not 1 <= page_size <= 100:
        raise ValueError("page_size must be between 1 and 100")
    return page_size


def _parse_features(value) -> list:
    if isinstance(value, str):
        return [value]
    if isinstance(value, list):
        return [str(feature) for feature in value]
    raise ValueError("features must be a string or list")


_PARSERS = {
    "debug": _parse_debug,
    "page_size": _parse_page_size,
    "features": _parse_features,
}


def parse_config(raw: dict) -> dict:
    if not isinstance(raw, dict):
        raise TypeError("config must be a dictionary")

    parsed = {
        key: (list(value) if isinstance(value, list) else value)
        for key, value in _DEFAULTS.items()
    }

    for key, parser in _PARSERS.items():
        if key in raw:
            parsed[key] = parser(raw[key])

    return parsed

